const rows = $input.all();

const enabledRows = rows.filter(item => {
  const enabled = String(item.json.enabled).toLowerCase();
  return enabled === 'true';
});

return enabledRows.map(item => {
  return {
    json: {
      symbol: item.json.symbol,
      exchange: item.json.exchange,
      scan_mode: item.json.scan_mode,
      strike_count: Number(item.json.strike_count || 10)
    }
  };
});

const input = $input.first().json;

const contracts = input.data || [];

return contracts.map(contract => {
  return {
    json: {
      captured_at: input.captured_at,
      source: input.source,
      symbol: contract.symbol,
      expiry: contract.expiry,
      strike: Number(contract.strike),
      option_type: contract.option_type,
      ltp: Number(contract.ltp || 0),
      volume: Number(contract.volume || 0),
      open_interest: Number(contract.open_interest || 0),
      change_in_oi: Number(contract.change_in_oi || 0),
      iv: Number(contract.iv || 0),
      underlying_price: Number(contract.underlying_price || 0)
    }
  };
});

const items = $input.all();

function average(values) {
  if (!values.length) return 0;
  return values.reduce((sum, value) => sum + value, 0) / values.length;
}

function standardDeviation(values) {
  if (values.length < 2) return 0;

  const avg = average(values);
  const variance = average(values.map(value => Math.pow(value - avg, 2)));

  return Math.sqrt(variance);
}

const results = [];

for (const item of items) {
  const data = item.json;

  const historicalVolume = Number(data.historical_avg_volume || 400000);
  const historicalOI = Number(data.historical_avg_oi || 500000);

  const volume = Number(data.volume || 0);
  const openInterest = Number(data.open_interest || 0);

  const volumeRatio = historicalVolume > 0 ? volume / historicalVolume : 0;
  const oiRatio = historicalOI > 0 ? openInterest / historicalOI : 0;

  const historicalRatios = [
    0.85,
    0.92,
    1.05,
    0.98,
    1.1,
    0.95,
    1.02,
    1.08,
    0.91,
    1.0
  ];

  const avgRatio = average(historicalRatios);
  const sdRatio = standardDeviation(historicalRatios);

  const zScore = sdRatio > 0 ? (volumeRatio - avgRatio) / sdRatio : 0;

  let anomalyType = 'normal';

  if (volumeRatio >= 3 && oiRatio >= 2) {
    anomalyType = 'volume_and_oi_spike';
  } else if (volumeRatio >= 3) {
    anomalyType = 'volume_spike';
  } else if (oiRatio >= 2) {
    anomalyType = 'oi_spike';
  } else if (zScore >= 3) {
    anomalyType = 'statistical_anomaly';
  }

  const anomaly = volumeRatio >= 3 || oiRatio >= 2 || zScore >= 3;

  results.push({
    json: {
      ...data,
      avg_volume_20d: historicalVolume,
      avg_oi_20d: historicalOI,
      volume_ratio: Number(volumeRatio.toFixed(2)),
      oi_ratio: Number(oiRatio.toFixed(2)),
      z_score: Number(zScore.toFixed(2)),
      anomaly_type: anomalyType,
      anomaly
    }
  });
}

return results;

