const items = $input.all();

if (items.length === 0) {
  return [
    {
      json: {
        subject: 'NSE Options Anomaly Alert',
        body: 'No anomalies detected.'
      }
    }
  ];
}

const formatNumber = (value) => {
  const number = Number(value);

  if (Number.isNaN(number)) {
    return value ?? '';
  }

  return number.toLocaleString('en-IN');
};

const formatRatio = (value) => {
  const number = Number(value);

  if (Number.isNaN(number)) {
    return value ?? '';
  }

  return number.toFixed(2) + 'x';
};

const formatText = (value) => {
  if (!value) {
    return '';
  }

  return String(value)
    .replace(/\r\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
};

const anomalies = items.map((item, index) => {
  const data = item.json;

  return {
    number: index + 1,
    timestamp: data.timestamp || data.detected_at || '',
    symbol: data.symbol || '',
    expiry: data.expiry || '',
    strike: data.strike || '',
    option_type: data.option_type || '',
    ltp: data.ltp || '',
    volume: data.volume || 0,
    open_interest: data.open_interest || 0,
    avg_volume_20d: data.avg_volume_20d || 0,
    avg_oi_20d: data.avg_oi_20d || 0,
    volume_ratio: data.volume_ratio || 0,
    oi_ratio: data.oi_ratio || 0,
    z_score: data.z_score || 0,
    anomaly_type: data.anomaly_type || '',
    ai_interpretation: formatText(data.ai_interpretation || '')
  };
});

const sections = anomalies.map((data) => {
  return `
ANOMALY ${data.number}

Symbol: ${data.symbol}
Expiry: ${data.expiry}
Strike: ${data.strike}
Option Type: ${data.option_type}
LTP: ${formatNumber(data.ltp)}

Current Volume: ${formatNumber(data.volume)}
20 Day Average Volume: ${formatNumber(data.avg_volume_20d)}
Volume Ratio: ${formatRatio(data.volume_ratio)}

Current Open Interest: ${formatNumber(data.open_interest)}
20 Day Average Open Interest: ${formatNumber(data.avg_oi_20d)}
OI Ratio: ${formatRatio(data.oi_ratio)}

Z Score: ${data.z_score}
Anomaly Type: ${data.anomaly_type}

AI Interpretation

${data.ai_interpretation}
`;
});

const subject =
  `NSE Options Anomaly Alert: ${anomalies.length} Anomalies Detected`;

const body = `
NSE OPTIONS ANOMALY ALERT

Total Anomalies Detected: ${anomalies.length}

The following option contracts have been flagged based on unusual volume, open interest or statistical activity.

${sections.join('\n----------------------------------------\n')}

SUMMARY

Total Anomalies: ${anomalies.length}

Anomaly Types:

${anomalies
  .reduce((counts, anomaly) => {
    counts[anomaly.anomaly_type] =
      (counts[anomaly.anomaly_type] || 0) + 1;

    return counts;
  }, {})
  ? Object.entries(
      anomalies.reduce((counts, anomaly) => {
        counts[anomaly.anomaly_type] =
          (counts[anomaly.anomaly_type] || 0) + 1;

        return counts;
      }, {})
    )
      .map(([type, count]) => `${type}: ${count}`)
      .join('\n')
  : 'None'}

RISK NOTE

These alerts identify unusual options activity only.

They do not confirm institutional activity, smart money activity, or future market direction.

Volume and open interest should be evaluated together with price movement, implied volatility, change in open interest, market trend, news, expiry context and other relevant factors.

The AI interpretation is informational and should not be treated as a trading recommendation.
`;

return [
  {
    json: {
      subject,
      body,
      anomaly_count: anomalies.length
    }
  }
];
